package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import androidx.activity.result.ActivityResultLauncher;import androidx.health.connect.client.PermissionController;import androidx.health.connect.client.HealthConnectClient;import java.util.*;
/** Board32 real sleep permissions and explicit manual sync; no automatic account/data access. */
public final class HealthConnectActivity extends ComponentActivity {
 private HealthSleepJobs.Job job;private HealthSleepJobs.State drawn;private Records.Factory records;private final Handler main=new Handler(Looper.getMainLooper());private boolean resumed,review;private int shown=10;private String permissionError="";private Dialog confirmation;
 private static final String DENIED="Sleep permissions were not fully granted. You can change them in Health Connect.";private ActivityResultLauncher<Set<String>> permissionRequest;
 // This Activity uses ComponentActivity directly; there is no FragmentActivity or legacy Fragment dependency.
 @android.annotation.SuppressLint("InvalidFragmentVersionForActivityResult")
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);records=Records.factory;job=HealthSleepJobs.get(this,records);permissionRequest=registerForActivityResult(PermissionController.Companion.createRequestPermissionResultContract(),granted->{permissionError=granted.containsAll(wanted())?"":DENIED;job.inspect();render();});if(state!=null){review=state.getBoolean("review");shown=state.getInt("shown",10);permissionError=state.getString("permissionError","");}getOnBackPressedDispatcher().addCallback(this,new androidx.activity.OnBackPressedCallback(true){@Override public void handleOnBackPressed(){back();}});render();}
 @Override protected void onResume(){super.onResume();resumed=true;job.inspect();poll.run();}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);closeConfirmation();super.onPause();}
 private boolean read(){return job.prefs.getBoolean("healthImport",false);}private boolean write(){return job.prefs.getBoolean("healthExport",false);}private Set<String> wanted(){Set<String> out=new HashSet<>();if(read())out.add(HealthSleepPort.READ);if(write())out.add(HealthSleepPort.WRITE);return out;}
 private void render(){HealthSleepJobs.State s=job.state;drawn=s;if(!s.busy&&s.access.available()&&!wanted().isEmpty()&&s.access.granted.containsAll(wanted())&&DENIED.equals(permissionError))permissionError="";LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);if(review){RecordUi.header(body,"Provider changes",this::back);changes(body,s);return;}
  LinearLayout navigation=Design.row(this);RecordUi.headerAction(navigation,"back","Back",this::back);navigation.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));RecordUi.menuAction(navigation,"Health Connect options",this::options,false);body.addView(navigation);Design.space(body,12);Design.text(body,"Health Connect",30,700,Design.INK);Design.space(body,6);Design.text(body,"Exchange sleep records with Android",15,400,Design.MUTED);Design.space(body,22);
  LinearLayout card=Design.row(this);Design.pad(card,18,20);card.setBackground(Design.shape(this,Design.SOFT,20));ImageView mark=new ImageView(this);mark.setImageResource(R.drawable.health_connect_logo);mark.setScaleType(ImageView.ScaleType.FIT_CENTER);mark.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);Design.pad(mark,8,8);mark.setBackground(Design.shape(this,Color.WHITE,16));card.addView(mark,new LinearLayout.LayoutParams(Design.dp(this,64),Design.dp(this,64)));LinearLayout status=Design.col(this);status.setPadding(Design.dp(this,16),0,0,0);boolean granted=!wanted().isEmpty()&&s.access.granted.containsAll(wanted());Design.text(status,s.access.availability<0?"Checking availability":!s.access.available()?s.access.availability==1?"Update needed":"Unavailable":granted?"Connected":"Not connected",20,600,Design.INK);Design.space(status,6);Design.text(status,s.access.available()?(granted?"Ready to sync your chosen sleep records.":wanted().isEmpty()?"Turn on Import or Export below.":"Connect to allow the selected sleep access."):"Health Connect is not ready on this device.",13,400,Design.MUTED);card.addView(status,new LinearLayout.LayoutParams(0,-2,1));body.addView(card);Design.space(body,10);
  toggle(body,"download","Import sleep records","Read sleep sessions from Health Connect.",read(),value->job.prefs.edit().putBoolean("healthImport",value).apply());Design.line(body);toggle(body,"upload","Export sleep records","Share completed SleepWell sleep sessions.",write(),value->job.prefs.edit().putBoolean("healthExport",value).apply());Design.space(body,16);Design.line(body);
  PlanActivity.detail(body,"file","Permissions",permissionSummary(s),null,this::permissions);PlanActivity.detail(body,"clock","Last sync",s.last==0?"Never":RecordUi.date(s.last,java.time.ZoneId.systemDefault())+" · "+RecordUi.clock(this,s.last,java.time.ZoneId.systemDefault()),null,null);
  if(!s.message.isEmpty()){Design.space(body,8);Design.text(body,s.message,13,400,Design.MUTED);}if(!s.conflicts.isEmpty())PlanActivity.detail(body,"report","Review provider changes","Your local edits were kept",s.conflicts.size()+" waiting",()->{review=true;render();});
  LinearLayout footer=RecordUi.footer(body);footer.setPadding(Design.dp(this,24),0,Design.dp(this,24),Design.dp(this,8));String error=!permissionError.isEmpty()?permissionError:s.error;if(!error.isEmpty()){Design.text(footer,error,13,500,Design.BROWN);Design.space(footer,8);}if(s.busy){Design.text(footer,"Working with sleep records…",14,500,Design.INK);Design.button(footer,"Cancel sync",false,()->{job.cancel();permissionError="Cancel requested. Completed changes are kept.";render();});}else if(s.access.availability==1){Design.button(footer,"Install or update Health Connect",true,this::install);}else if(!s.access.available()){Design.button(footer,"Check again",true,job::inspect);}else{boolean chosen=!wanted().isEmpty();Button primary=Design.button(footer,granted?"Sync now":"Connect Health Connect",true,()->{permissionError="";if(granted)job.sync(read(),write());else request();render();});if(!granted)connectGlyph(primary);primary.setEnabled(chosen);primary.setAlpha(chosen?1f:.45f);}compactAction(footer);
 }
 private void connectGlyph(Button button){
  button.setCompoundDrawablesRelative(RecordUi.glyph(this,"link",Design.CREAM,20),null,null,null);button.setCompoundDrawablePadding(Design.dp(this,8));
  button.addOnLayoutChangeListener((view,l,t,r,b,ol,ot,or,ob)->{int label=(int)Math.ceil(android.text.Layout.getDesiredWidth(button.getText(),button.getPaint()));int group=label+Design.dp(this,28);int pad=Math.max(Design.dp(this,12),(button.getWidth()-group)/2);if(button.getPaddingLeft()!=pad||button.getPaddingRight()!=pad)button.setPadding(pad,button.getPaddingTop(),pad,button.getPaddingBottom());});
 }
 private String permissionSummary(HealthSleepJobs.State state){if(state.access.availability<0)return "Checking Android sleep access…";if(!state.access.available())return "Managed by Android";if(wanted().isEmpty())return "No sleep access selected";List<String> parts=new ArrayList<>();if(read())parts.add(state.access.granted.contains(HealthSleepPort.READ)?"Import allowed":"Import access needed");if(write())parts.add(state.access.granted.contains(HealthSleepPort.WRITE)?"Export allowed":"Export access needed");return String.join(" · ",parts);}
 private void compactAction(LinearLayout footer){for(int n=0;n<footer.getChildCount();n++)if(footer.getChildAt(n) instanceof Button){Button action=(Button)footer.getChildAt(n);LinearLayout.LayoutParams size=(LinearLayout.LayoutParams)action.getLayoutParams();size.topMargin=Design.dp(this,n==0?0:8);action.setLayoutParams(size);}}
 private void toggle(LinearLayout body,String icon,String title,String subtitle,boolean value,java.util.function.Consumer<Boolean> save){LinearLayout row=Design.row(this);Design.Icon glyph=new Design.Icon(this,icon,Design.BROWN);LinearLayout.LayoutParams glyphSize=new LinearLayout.LayoutParams(Design.dp(this,28),Design.dp(this,28));glyphSize.rightMargin=Design.dp(this,16);row.addView(glyph,glyphSize);LinearLayout text=Design.col(this);Design.text(text,title,16,600,Design.INK);Design.space(text,5);Design.text(text,subtitle,12,400,Design.MUTED);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));InteractionFeedback.Toggle control=new InteractionFeedback.Toggle(this);control.setChecked(value);Design.styleSwitch(this,control,Design.BROWN,0xffbcb5b0);control.setContentDescription(title);control.setEnabled(!job.state.busy);control.setOnCheckedChangeListener((button,checked)->{control.userChanged();save.accept(checked);permissionError="";render();});LinearLayout.LayoutParams controlSize=new LinearLayout.LayoutParams(Design.dp(this,58),Design.dp(this,64));controlSize.leftMargin=Design.dp(this,12);row.addView(control,controlSize);row.setMinimumHeight(Design.dp(this,88));row.setBackground(Design.touch(this,Color.TRANSPARENT,12));row.setOnClickListener(view->{if(control.isEnabled())control.performClick();});body.addView(row);}
 private void options(){
  Dialog dialog=new Dialog(this);track(dialog);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout body=Design.col(this);Design.pad(body,22,20);body.setBackground(Design.shape(this,Design.CREAM,24));Design.text(body,"Health Connect options",22,600,Design.INK);Design.space(body,14);
  PlanActivity.detail(body,"info","What is exchanged","Sleep records, stages and local changes",null,()->{closeConfirmation();confirmation=SleepPicker.message(this,"Sleep exchange","Sync runs when you choose Sync now. Imports include their provider and reported stages. Local edits are kept until you review provider changes. Deleting an imported copy hides it locally. Exports update only SleepWell’s own Health Connect copies. Audio is never shared. The initial import covers the last 30 days.");});Design.line(body);
  if(job.state.hidden>0){PlanActivity.detail(body,"undo","Allow hidden imports again",job.state.hidden+" copies hidden locally",null,()->{closeConfirmation();allowHidden();});Design.line(body);}
  PlanActivity.detail(body,"lock","Android permissions","Review or revoke sleep access",null,()->{closeConfirmation();permissions();});Design.button(body,"Done",false,dialog::dismiss);ScrollView scroll=new ScrollView(this);scroll.addView(body);dialog.setContentView(scroll);SleepPicker.show(this,dialog,440);
 }
 private void request(){if(wanted().isEmpty())return;try{permissionRequest.launch(wanted());}catch(RuntimeException failure){permissionError="Android could not open sleep permissions. Open Health Connect settings and try again.";render();}}
 private void permissions(){try{Intent intent=new Intent(HealthConnectClient.getHealthConnectSettingsAction());if(Build.VERSION.SDK_INT<34)intent.setPackage("com.google.android.apps.healthdata");startActivity(intent);}catch(RuntimeException failure){permissionError="Health Connect settings are unavailable. Check installation and Android profile.";render();}}
 private void install(){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("market://details?id=com.google.android.apps.healthdata")).setPackage("com.android.vending"));}catch(RuntimeException failure){permissionError="Install Health Connect from Google Play, then return and check again.";render();}}
 private void changes(LinearLayout body,HealthSleepJobs.State s){Design.space(body,12);Design.text(body,"Choose what to keep",21,600,Design.INK);Design.space(body,8);Design.text(body,"Local edits stay unchanged until you choose.",14,400,Design.MUTED);int count=0;for(HealthSleepJobs.Conflict conflict:s.conflicts){if(count++>=shown)break;PlanActivity.detail(body,"report",conflict.origin,conflict.payload.isEmpty()?"Provider deleted this session":"Provider changed this session",null,()->confirm(conflict));Design.line(body);}if(s.conflicts.isEmpty())Design.text(body,"No provider changes need review.",15,400,Design.MUTED);if(s.conflicts.size()>shown)Design.button(body,"Show more",false,()->{shown+=10;render();});if(!s.error.isEmpty())Design.text(body,s.error,13,500,Design.BROWN);if(s.busy)Design.text(body,"Applying your choice…",14,500,Design.INK);}
 private void confirm(HealthSleepJobs.Conflict conflict){if(job.state.busy)return;Dialog dialog=new Dialog(this);track(dialog);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout content=Design.col(this);Design.pad(content,22,22);content.setBackground(Design.shape(this,Design.CREAM,24));Design.text(content,conflict.payload.isEmpty()?"Provider deleted this sleep":"Provider changed this sleep",21,600,Design.INK);Design.space(content,16);Design.text(content,"Choose the provider version or keep your local edited copy. Other records stay unchanged.",14,400,Design.MUTED);Design.button(content,conflict.payload.isEmpty()?"Use provider deletion":"Use provider version",true,()->{if(!owns(dialog))return;closeConfirmation();job.resolve(conflict,true);render();});Design.button(content,"Keep local copy",false,()->{if(!owns(dialog))return;closeConfirmation();job.resolve(conflict,false);render();});Design.button(content,"Cancel",false,dialog::dismiss);dialog.setContentView(content);dialog.show();dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));dialog.getWindow().setLayout(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),-2);}
 private void allowHidden(){Dialog dialog=new Dialog(this);track(dialog);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout body=Design.col(this);Design.pad(body,22,22);body.setBackground(Design.shape(this,Design.CREAM,24));Design.text(body,"Allow hidden imports again?",21,600,Design.INK);Design.space(body,16);Design.text(body,"Previously deleted imported copies can return on your next manual sync. No data is read now.",14,400,Design.MUTED);Design.button(body,"Allow imports again",true,()->{if(!owns(dialog))return;closeConfirmation();job.allowHidden();render();});Design.button(body,"Cancel",false,dialog::dismiss);dialog.setContentView(body);dialog.show();dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));dialog.getWindow().setLayout(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),-2);}
 private final Runnable poll=new Runnable(){public void run(){if(!resumed)return;if(drawn!=job.state)render();main.postDelayed(this,100);}};
 private boolean owns(Dialog dialog){return confirmation==dialog&&resumed&&!isFinishing()&&!isDestroyed()&&dialog.isShowing();}
 private void track(Dialog dialog){closeConfirmation();confirmation=dialog;dialog.setOnDismissListener(ignored->{if(confirmation==dialog)confirmation=null;});}
 private void closeConfirmation(){Dialog dialog=confirmation;confirmation=null;if(dialog!=null)dialog.dismiss();}
 private void back(){if(confirmation!=null&&confirmation.isShowing()){closeConfirmation();return;}if(review){review=false;render();}else finish();}
 @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("review",review);state.putInt("shown",shown);state.putString("permissionError",permissionError);}@Override protected void onDestroy(){main.removeCallbacks(poll);closeConfirmation();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
